command:
cat > "$TMPDIR/patch-batch2-205.mjs" <<'EOF'
import { readFileSync, writeFileSync } from 'node:fs';
const p = process.argv[2];
let s = readFileSync(p, 'utf8');
const anchor = "edit('SPEC.md', [[VERB_TAIL, VERB_NEW, 'journal verbs'], [ADV_TAIL, ADV_NEW, 'advance cadence + journal paragraph'], [S7_TAIL, S7_NEW, 'section 7 journal sentence']]);";
if (s.split(anchor).length !== 2) throw new Error('anchor');
const add = "const T_ANCHOR = \"\\nThe reference runtime gives that boundary a definite shape. An adapter implements one method\";\n" +
"const T_NEW = \"\\nAn executor that spawns a child MUST construct that child's environment rather than inherit one. It MUST withhold every variable whose name falls under the credential-bearing prefixes the runtime maintains (`APPROVAL_`, `TELEGRAM_`, `VAULT_`), less the runtime's own declared non-secret names, and MUST withhold the variable named by `vault.passphrase_env` wherever that name falls. It MUST pass the credentials the adapter serving the action's class declared in `requiredCredentials`, and MUST NOT accept any other instruction, from a flag or from a payload, about which variables to pass. Every other variable passes through unchanged. The `execution.started` record MUST carry `env_stripped`, the count of variables withheld, and MUST NOT carry their names or their values. This is a credential scrub and not a sandbox: the child retains the network and filesystem capability of the process that spawned it. (Amended APRV-205, pending sign-off.)\\n\" + T_ANCHOR;\n" +
"edit('SPEC.md', [[VERB_TAIL, VERB_NEW, 'journal verbs'], [ADV_TAIL, ADV_NEW, 'advance cadence + journal paragraph'], [S7_TAIL, S7_NEW, 'section 7 journal sentence'], [T_ANCHOR, T_NEW, 'section 10.4 child environment']]);";
writeFileSync(p, s.replace(anchor, add));
console.log('patched');
EOF
node "$TMPDIR/patch-batch2-205.mjs" "$TMPDIR/apply-batch2.mjs" && rm -rf "$TMPDIR/dry2" && mkdir -p "$TMPDIR/dry2" && cp SPEC.md "$TMPDIR/dry2/" && cp CLAUDE.md "$TMPDIR/dry2/" && cp AGENTS.md "$TMPDIR/dry2/" && node "$TMPDIR/apply-batch2.mjs" "$TMPDIR/dry2" SPEC.md CLAUDE.md AGENTS.md | tail -1 && diff SPEC.md "$TMPDIR/dry2/SPEC.md" | grep -c '^>'
